/**
 * Расчёт законной пени ЖКУ (ч. 14 / 14.1 ст. 155 ЖК РФ) по периодам парсера.
 *
 * Профили (связка макетов ↔ расчёт), выбор только при видимом п.3:
 * 1.1 — опции: 1, 2, 3.1, 5.1, 6.1, 6.3, 7.1
 *   срок оплаты: 15 числа след. месяца; старт пени: 15+31;
 *   пеня = задолженность × 1/300 × дни × ставка; ставка 9,5% до 01.01.2027
 * 1.2 — опция: 8.1
 *   срок оплаты: 15 числа след. месяца; старт пени: 15+1;
 *   пеня = задолженность × 1/130 × дни × ставка; ставка 9,5% до 01.01.2027
 * 2.1 — опции: 5.2, 6.2, 6.4, 8.2
 *   срок оплаты: 10 числа след. месяца; старт пени: 10+1;
 *   пеня = задолженность × 1/130 × дни × ставка ЦБ на дату расчёта
 * 2.2 — опция: 3.2
 *   срок оплаты: 18 числа след. месяца; старт пени: 18+1;
 *   пеня = задолженность × 1/130 × дни × ставка ЦБ на дату расчёта
 * 2.3 — опция: 7.2
 *   срок оплаты: 25 числа след. месяца; старт пени: 25+1;
 *   пеня = задолженность × 1/130 × дни × ставка ЦБ на дату расчёта
 * 3.x — по мере внедрения
 *
 * Если п.3 скрыт или опция не совпала с профилем — дефолт:
 *   1/300, старт 15+31, ставка 9,5%
 *
 * Общее:
 * - оплаты до старта только уменьшают долг
 * - после старта: отрезок с → по (дата оплаты), затем оплата; следующий «с» = по + 1
 * - оплаты и отрезки не позже asOfDate; начисления позже asOfDate не входят
 * - по умолчанию фиксированная ставка 9,5%; история ЦБ — options.rateSource: 'cbr'
 * - ставка на дату расчёта — options.rateSource: 'cbrAsOf'
 */

/** Опции п.3 для расчёта 1.1 */
export const PENALTY_CALC_1_1_OPTS = ['1', '2', '3.1', '5.1', '6.1', '6.3', '7.1'];

/** Опции п.3 для расчёта 1.2 */
export const PENALTY_CALC_1_2_OPTS = ['8.1'];

/** Опции п.3 для расчёта 2.1 (арб. 3–8: «прочие» + ТКО 8.2) */
export const PENALTY_CALC_2_1_OPTS = ['5.2', '6.2', '6.4', '8.2'];

/** Опции п.3 для расчёта 2.2 */
export const PENALTY_CALC_2_2_OPTS = ['3.2'];

/** Опции п.3 для расчёта 2.3 */
export const PENALTY_CALC_2_3_OPTS = ['7.2'];

const RATE_095 = { rate: 0.095 };
const PROFILE_1_1 = { ...RATE_095, graceDays: 15, delayDays: 31, dailyDivisor: 300, profile: '1.1' };
const PROFILE_1_2 = { ...RATE_095, graceDays: 15, delayDays: 1, dailyDivisor: 130, profile: '1.2' };
const PROFILE_2_1 = {
  graceDays: 10,
  delayDays: 1,
  dailyDivisor: 130,
  rateSource: 'cbrAsOf',
  profile: '2.1',
};
const PROFILE_2_2 = {
  graceDays: 18,
  delayDays: 1,
  dailyDivisor: 130,
  rateSource: 'cbrAsOf',
  profile: '2.2',
};
const PROFILE_2_3 = {
  graceDays: 25,
  delayDays: 1,
  dailyDivisor: 130,
  rateSource: 'cbrAsOf',
  profile: '2.3',
};

/** Дефолт (как было до разведения профилей). */
function defaultHousingPenaltyOptions() {
  return { ...RATE_095, graceDays: 15, delayDays: 31, dailyDivisor: 300, profile: 'default' };
}

/**
 * Параметры расчёта пени по опции п.3.
 * @param {string} requirements
 * @param {{ showRequirements?: boolean }} [ctx]
 */
export function housingPenaltyOptionsForRequirements(requirements, ctx = {}) {
  const req = String(requirements || '');
  const showRequirements = ctx.showRequirements === true;

  if (showRequirements && PENALTY_CALC_1_1_OPTS.includes(req)) {
    return { ...PROFILE_1_1 };
  }

  if (showRequirements && PENALTY_CALC_1_2_OPTS.includes(req)) {
    return { ...PROFILE_1_2 };
  }

  if (showRequirements && PENALTY_CALC_2_1_OPTS.includes(req)) {
    return { ...PROFILE_2_1 };
  }

  if (showRequirements && PENALTY_CALC_2_2_OPTS.includes(req)) {
    return { ...PROFILE_2_2 };
  }

  if (showRequirements && PENALTY_CALC_2_3_OPTS.includes(req)) {
    return { ...PROFILE_2_3 };
  }

  // иначе — дефолт
  return defaultHousingPenaltyOptions();
}

import { getKeyRateAt, getKeyRateChangeDatesBetween } from './cbrKeyRates';

const DATE_RE = /^(\d{2})\.(\d{2})\.(\d{4})$/;

export function parseRuDate(value) {
  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    // Календарный день по локали, храним как UTC-полночь (без сдвига часового пояса).
    return new Date(Date.UTC(value.getFullYear(), value.getMonth(), value.getDate()));
  }
  const match = String(value || '')
    .trim()
    .match(DATE_RE);
  if (!match) return null;
  return new Date(Date.UTC(Number(match[3]), Number(match[2]) - 1, Number(match[1])));
}

export function formatRuDate(date) {
  if (!date) return '';
  const dd = String(date.getUTCDate()).padStart(2, '0');
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  return `${dd}.${mm}.${date.getUTCFullYear()}`;
}

/** Сегодняшняя дата в локали пользователя (дд.мм.гггг). */
export function todayRuDate() {
  const now = new Date();
  const dd = String(now.getDate()).padStart(2, '0');
  const mm = String(now.getMonth() + 1).padStart(2, '0');
  return `${dd}.${mm}.${now.getFullYear()}`;
}

export function addDays(date, days) {
  const next = new Date(date.getTime());
  next.setUTCDate(next.getUTCDate() + days);
  return next;
}

export function daysBetween(from, to) {
  return Math.round((to.getTime() - from.getTime()) / 86400000);
}

function toAmount(value) {
  if (value == null || value === '' || value === '-' || value === '---') return 0;
  if (typeof value === 'number') return Number.isFinite(value) ? value : 0;

  let s = String(value)
    .replace(/\u00a0/g, '')
    .replace(/\s/g, '')
    .trim();
  if (!s || s === '-' || s === '---') return 0;

  // 1,234,567.89
  if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) {
    s = s.replace(/,/g, '');
  } else if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) {
    // 1.234.567,89
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (s.includes(',') && s.includes('.')) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) {
      s = s.replace(/\./g, '').replace(',', '.');
    } else {
      s = s.replace(/,/g, '');
    }
  } else if (s.includes(',')) {
    s = s.replace(',', '.');
  }

  const num = Number(s);
  return Number.isFinite(num) ? num : 0;
}

function roundMoney(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function pushSegment(segments, { debt, from, to, rate, closedByPayment, dailyDivisor }) {
  if (!(debt > 0) || to.getTime() <= from.getTime()) return;
  const days = daysBetween(from, to);
  if (days <= 0) return;
  const divisor = dailyDivisor > 0 ? dailyDivisor : 300;
  segments.push({
    debt: roundMoney(debt),
    from: formatRuDate(from),
    to: formatRuDate(to),
    days,
    rate,
    dailyDivisor: divisor,
    penalty: roundMoney(debt * (1 / divisor) * days * rate),
    closedByPayment: Boolean(closedByPayment),
  });
}

function resolveRate(date, fixedRate) {
  if (fixedRate != null) return fixedRate;
  return getKeyRateAt(date);
}

/** Режет отрезок по сменам ключевой ставки ЦБ. */
function pushSegmentWithRates(segments, { debt, from, to, fixedRate, closedByPayment, dailyDivisor }) {
  if (!(debt > 0) || to.getTime() <= from.getTime()) return;

  const changeDates = fixedRate != null ? [] : getKeyRateChangeDatesBetween(from, to);
  const ends = [...changeDates, to];
  let start = from;

  for (let i = 0; i < ends.length; i += 1) {
    const end = ends[i];
    const isLast = i === ends.length - 1;
    pushSegment(segments, {
      debt,
      from: start,
      to: end,
      rate: resolveRate(start, fixedRate),
      closedByPayment: closedByPayment && isLast,
      dailyDivisor,
    });
    start = end;
  }
}

/**
 * @param {Array<{ accrual?: { date: string, amount: string|number, label?: string }|null, payments?: Array<{ date: string, amount: string|number, label?: string }> }>} periods
 * @param {{ asOfDate?: string|Date, rate?: number, rateSource?: 'fixed'|'cbr'|'cbrAsOf', graceDays?: number, delayDays?: number, dailyDivisor?: number, profile?: string }} [options]
 *   rate — фиксированная доля (0.095 = 9.5%), по умолчанию
 *   rateSource: 'cbr' — ставка ЦБ по дням; 'cbrAsOf' — одна ставка ЦБ на дату расчёта (профиль 2.1)
 *   dailyDivisor: 300 (ЖКУ) или 130 (ТКО / «прочие»)
 */
export function calculateHousingPenalty(periods, options = {}) {
  const asOfDate = parseRuDate(options.asOfDate) || parseRuDate(todayRuDate());
  const rateSource = options.rateSource || 'fixed';
  let fixedRate;
  if (rateSource === 'cbr') {
    fixedRate = null;
  } else if (rateSource === 'cbrAsOf') {
    fixedRate = getKeyRateAt(asOfDate);
  } else if (options.rate != null && Number.isFinite(Number(options.rate))) {
    fixedRate = Number(options.rate);
  } else {
    fixedRate = 0.095;
  }
  const graceDays = options.graceDays != null ? Number(options.graceDays) : 15;
  const delayDays = options.delayDays != null ? Number(options.delayDays) : 31;
  const dailyDivisor = options.dailyDivisor != null ? Number(options.dailyDivisor) : 300;

  const periodResults = [];
  let principalTotal = 0;
  let penaltyTotal = 0;

  for (const period of periods || []) {
    const result = calculatePeriodPenalty(period, {
      asOfDate,
      fixedRate,
      graceDays,
      delayDays,
      dailyDivisor,
    });
    periodResults.push(result);
    principalTotal += result.remainingDebt;
    penaltyTotal += result.penaltyTotal;
  }

  return {
    asOfDate: formatRuDate(asOfDate),
    rate: fixedRate,
    rateSource: rateSource === 'cbr' ? 'cbr' : rateSource === 'cbrAsOf' ? 'cbrAsOf' : 'fixed',
    dailyDivisor,
    profile: options.profile || 'default',
    periods: periodResults,
    principalTotal: roundMoney(principalTotal),
    penaltyTotal: roundMoney(penaltyTotal),
    claimAmount: roundMoney(principalTotal + penaltyTotal),
  };
}

function calculatePeriodPenalty(period, { asOfDate, fixedRate, graceDays, delayDays, dailyDivisor }) {
  const accrual = period?.accrual || null;
  const accrualDate = accrual ? parseRuDate(accrual.date) : null;
  const accrualAmount = accrual ? toAmount(accrual.amount) : 0;
  const payments = (period?.payments || [])
    .map((p) => ({
      date: parseRuDate(p.date),
      amount: toAmount(p.amount),
      label: p.label || '',
    }))
    .filter((p) => p.date && p.amount)
    .sort((a, b) => a.date - b.date);

  if (!accrualDate || !accrualAmount) {
    return {
      accrual,
      penaltyStartDate: null,
      remainingDebt: 0,
      penaltyTotal: 0,
      segments: [],
      paymentRows: [],
      excludedAfterAsOf: false,
    };
  }

  // Счёт-фактура ещё не выставлена на дату расчёта — период не входит в иск.
  if (accrualDate.getTime() > asOfDate.getTime()) {
    return {
      accrual: {
        date: formatRuDate(accrualDate),
        amount: accrualAmount,
        label: accrual.label || '',
      },
      penaltyStartDate: formatRuDate(addDays(accrualDate, graceDays + delayDays)),
      remainingDebt: 0,
      penaltyTotal: 0,
      segments: [],
      paymentRows: (period?.payments || []).map((p) => ({
        date: p.date,
        amount: toAmount(p.amount),
        label: p.label || '',
        ignoredAfterAsOf: true,
      })),
      excludedAfterAsOf: true,
    };
  }

  const penaltyStartDate = addDays(accrualDate, graceDays + delayDays);
  let debt = accrualAmount;
  const segments = [];
  const paymentRows = [];

  // Оплаты после даты расчёта ещё не произошли — не учитываем.
  const applicablePayments = payments.filter((p) => p.date.getTime() <= asOfDate.getTime());
  const ignoredPayments = payments.filter((p) => p.date.getTime() > asOfDate.getTime());

  for (const payment of ignoredPayments) {
    paymentRows.push({
      date: formatRuDate(payment.date),
      amount: payment.amount,
      label: payment.label,
      ignoredAfterAsOf: true,
    });
  }

  // Старт пени ещё не наступил к asOf — только гасим долг оплатами.
  if (penaltyStartDate.getTime() > asOfDate.getTime()) {
    for (const payment of applicablePayments) {
      debt = roundMoney(debt - payment.amount);
      if (debt < 0) debt = 0;
      paymentRows.push({
        date: formatRuDate(payment.date),
        amount: payment.amount,
        label: payment.label,
        appliedBeforePenalty: true,
        debtAfter: debt,
      });
    }

    return {
      accrual: {
        date: formatRuDate(accrualDate),
        amount: accrualAmount,
        label: accrual.label || '',
      },
      penaltyStartDate: formatRuDate(penaltyStartDate),
      remainingDebt: roundMoney(debt),
      penaltyTotal: 0,
      segments,
      paymentRows,
      excludedAfterAsOf: false,
    };
  }

  const beforeStart = [];
  const afterStart = [];
  for (const payment of applicablePayments) {
    if (payment.date.getTime() <= penaltyStartDate.getTime()) beforeStart.push(payment);
    else afterStart.push(payment);
  }

  for (const payment of beforeStart) {
    debt = roundMoney(debt - payment.amount);
    if (debt < 0) debt = 0;
    paymentRows.push({
      date: formatRuDate(payment.date),
      amount: payment.amount,
      label: payment.label,
      appliedBeforePenalty: true,
      debtAfter: debt,
    });
  }

  let from = penaltyStartDate;

  for (const payment of afterStart) {
    const to = payment.date;
    pushSegmentWithRates(segments, {
      debt,
      from,
      to,
      fixedRate,
      closedByPayment: true,
      dailyDivisor,
    });
    if (to.getTime() > from.getTime()) {
      from = addDays(to, 1);
    }

    debt = roundMoney(debt - payment.amount);
    if (debt < 0) debt = 0;

    paymentRows.push({
      date: formatRuDate(payment.date),
      amount: payment.amount,
      label: payment.label,
      appliedBeforePenalty: false,
      debtAfter: debt,
    });
  }

  // Остаток на дату расчёта
  pushSegmentWithRates(segments, {
    debt,
    from,
    to: asOfDate,
    fixedRate,
    closedByPayment: false,
    dailyDivisor,
  });

  const penaltyTotal = roundMoney(segments.reduce((sum, s) => sum + s.penalty, 0));

  return {
    accrual: {
      date: formatRuDate(accrualDate),
      amount: accrualAmount,
      label: accrual.label || '',
    },
    penaltyStartDate: formatRuDate(penaltyStartDate),
    remainingDebt: roundMoney(debt),
    penaltyTotal,
    segments,
    paymentRows,
    excludedAfterAsOf: false,
  };
}
