/**
 * Макет: «исковое для арбитража - с 3 по 8.docx»
 * Вар.4/5 + опции 3.1…8. Без отсебятины.
 * Опции 8.1 (население/УК) и 8.2 (прочие) — ветки ТКО из образца.
 */
import { formatDutyAmount } from '../utils/calculateStateDuty';
import { addDays, formatRuDate, parseRuDate } from '../utils/calculateHousingPenalty';
import { debtorDisplayName, joinDebtorNames, resolveDebtors } from '../utils/resolveDebtors';

const PLACEHOLDER_COLOR = '#C00000';
/** В образце госпошлина фиксирована: 10 000 руб. */
const ARBITRATION_CLAIM_DUTY = '10\u00a0000';

function label(text) {
  return { text };
}

function placeholder(text) {
  return { text, italics: true, color: PLACEHOLDER_COLOR };
}

function plain(text) {
  return { text };
}

function field(value, placeholderText) {
  const text = value != null ? String(value).trim() : '';
  return text ? plain(text) : placeholder(placeholderText);
}

function headerLine(children) {
  return { text: children, alignment: 'right' };
}

function bodyParagraph(children) {
  return { text: children, alignment: 'justify', margin: [24, 0, 0, 8] };
}

function moneyField(value, placeholderText) {
  const n = Number(value);
  return n > 0 ? label(formatDutyAmount(n)) : placeholder(placeholderText);
}

function optionalHeaderLine(text) {
  const value = text != null ? String(text).trim() : '';
  return value ? [headerLine([plain(value)])] : [];
}

function penaltyPeriodRange(housingPenalty) {
  const periods = (housingPenalty?.periods || []).filter(
    (p) => !p.excludedAfterAsOf && p.penaltyTotal > 0 && p.segments?.length
  );
  if (!periods.length) return { from: '', to: '' };
  const from = periods[0].segments[0]?.from || periods[0].penaltyStartDate || '';
  const last = periods[periods.length - 1];
  const lastSeg = last.segments[last.segments.length - 1];
  const to = lastSeg?.to || housingPenalty.asOfDate || '';
  return { from, to };
}

function dayAfter(ruDate) {
  const d = parseRuDate(ruDate);
  return d ? formatRuDate(addDays(d, 1)) : '';
}

/** Образец: вставка, если пеня на задолженность, начисленную с 1.01.2027. */
function hasPenaltyOnDebtFrom2027(housingPenalty) {
  const cutoff = parseRuDate('01.01.2027');
  if (!cutoff) return false;
  return (housingPenalty?.periods || []).some((p) => {
    if (p.excludedAfterAsOf) return false;
    const accrual = parseRuDate(p.accrual?.date);
    return accrual && accrual.getTime() >= cutoff.getTime();
  });
}

function contractNoDateParts(form) {
  const number = String(form.contractInfo?.number || '').trim();
  const date = String(form.contractInfo?.date || '').trim();
  return { number, date };
}

/** 1/130 — «прочие» + ТКО 8.1/8.2; 1/300 — население/УК (кроме ТКО). */
function rateLabelForRequirements(requirements) {
  if (['5.1', '3.1', '6.1', '6.3', '7.1'].includes(requirements)) return '1/300';
  return '1/130';
}

/** Шапка ответчика: только заполненные поля. */
function defendantHeaderLines(person) {
  const name = String(person.fio || '').trim();
  const inn = String(person.inn || '').trim();
  const ogrn = String(person.ogrn || '').trim();
  const address = String(person.address || '').trim();
  const lines = [];
  if (name) lines.push(headerLine([plain(name)]));
  else if (inn) lines.push(headerLine([plain(`ИНН ${inn}`)]));
  if (ogrn) lines.push(headerLine([plain(`ОГРН ${ogrn}`)]));
  if (name && inn) lines.push(headerLine([plain(`ИНН ${inn}`)]));
  if (address) lines.push(headerLine([plain(address)]));
  return lines;
}

