/**
 * Источник данных: docs/podsudnost-soy.xlsx
 * Колонки: субъект РФ | город | улица | дом | мировой участок | районный/городской суд
 * Файл можно расширять — после правок пересобери data: node …/syncPodsudnostSoy.mjs
 * (или вызови parsePodsudnostSoyXlsx на ArrayBuffer файла).
 */

import * as XLSX from 'xlsx-js-style';

const HEADER_ALIASES = {
  region: ['субъект', 'субъект рф', 'регион'],
  city: ['город', 'поселок', 'посёлок', 'район', 'город / поселок / район'],
  street: ['улица', 'ул'],
  house: ['дом', 'д'],
  magistrate: ['мировой', 'участок', 'с/у', 'судебный участок'],
  districtCourt: ['районный', 'городской', 'суд'],
};

function norm(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function compactAddressPart(value) {
  return norm(value)
    .replace(/^(г\.|город|ул\.|улица|пр\.|проспект|пер\.|переулок|д\.|дом|корп\.|корпус|стр\.|строение)\s*/i, '')
    .replace(/[.,]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function scoreHeader(cell, aliases) {
  const text = norm(cell);
  if (!text) return 0;
  return aliases.some((a) => text.includes(a)) ? 1 : 0;
}

function detectHeaderRow(matrix) {
  let best = { index: 0, map: null, score: -1 };
  const limit = Math.min(matrix.length, 10);

  for (let r = 0; r < limit; r += 1) {
    const row = matrix[r] || [];
    const map = {};
    let score = 0;

    row.forEach((cell, c) => {
      Object.entries(HEADER_ALIASES).forEach(([key, aliases]) => {
        const s = scoreHeader(cell, aliases);
        if (s && (map[key] == null || s > 0)) {
          // Prefer first strong match; magistrate vs districtCourt both contain «суд»
          if (key === 'magistrate' && norm(cell).includes('мировой')) map[key] = c;
          else if (key === 'districtCourt' && (norm(cell).includes('район') || norm(cell).includes('городск'))) map[key] = c;
          else if (map[key] == null && key !== 'magistrate' && key !== 'districtCourt') map[key] = c;
          else if (map[key] == null && key === 'magistrate' && norm(cell).includes('участ')) map[key] = c;
          else if (map[key] == null && key === 'districtCourt') map[key] = c;
          score += s;
        }
      });
    });

    if (map.region != null && map.street != null && map.magistrate != null && score > best.score) {
      best = { index: r, map, score };
    }
  }

  // Fallback: фиксированные A–F как в примере ТЗ, без строки заголовка
  if (!best.map || best.score < 2) {
    return {
      index: -1,
      map: { region: 0, city: 1, street: 2, house: 3, magistrate: 4, districtCourt: 5 },
    };
  }
  return best;
}

function cell(row, index) {
  if (index == null) return '';
  const raw = row?.[index];
  return raw == null ? '' : String(raw).replace(/\u00a0/g, ' ').trim();
}

/**
 * @param {ArrayBuffer|Uint8Array|Buffer} buffer
 * @returns {{ rows: Array<{ region: string, city: string, street: string, house: string, magistrate: string, districtCourt: string }>, meta: object }}
 */
export function parsePodsudnostSoyXlsx(buffer) {
  const workbook = XLSX.read(buffer, { type: 'array', cellDates: true });
  const sheetName =
    workbook.SheetNames.find((n) => /подсудн|сою|soy/i.test(n)) || workbook.SheetNames[0];
  const sheet = workbook.Sheets[sheetName];
  const matrix = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '', raw: false });

  const { index: headerIndex, map } = detectHeaderRow(matrix);
  const rows = [];

  for (let r = headerIndex + 1; r < matrix.length; r += 1) {
    const row = matrix[r] || [];
    const region = cell(row, map.region);
    const street = cell(row, map.street);
    const magistrate = cell(row, map.magistrate);
    if (!region && !street && !magistrate) continue;

    rows.push({
      region,
      city: cell(row, map.city),
      street,
      house: cell(row, map.house),
      magistrate,
      districtCourt: cell(row, map.districtCourt),
    });
  }

  return {
    rows,
    meta: { sheetName, headerIndex, columns: map, total: rows.length },
  };
}

export { norm, compactAddressPart };
