/**
 * Поиск суда СОЮ по адресу должника.
 * Данные: docs/podsudnost-soy.xlsx → utils/podsudnostSoyData.js
 */

import { PODSUDNOST_SOY_ROWS } from './podsudnostSoyData';
import { compactAddressPart, norm } from './parsePodsudnostSoyXlsx';

export function emptySoyCourt() {
  return {
    found: false,
    kind: 'magistrate',
    source: '',
    sourceAddress: '',
    courtName: '',
    courtAddress: '',
    locality: '',
    raw: '',
    score: 0,
    parts: null,
    match: null,
    candidates: [],
  };
}

/**
 * Адрес для подсудности (ТЗ):
 * 1) п.8 / 8* — адрес должника
 * 2) если неизвестен — поле адреса текущего требования (3.1 / 3.1* / 3.2)
 */
export function getJurisdictionAddress(form = {}) {
  const debtor = (form.debtors && form.debtors[0]) || {};
  const loanDebtor = form.debtorLoan || {};
  const requirements = String(form.requirements || '');

  const pick = (value, source) => {
    const address = String(value || '').trim();
    return address ? { address, source } : null;
  };

  const fromDebtor = pick(debtor.address, 'debtor') || pick(loanDebtor.address, 'debtorLoan');

  if (requirements === '1' || requirements === '2') {
    return (
      pick(form.premisesAddress, 'premises') ||
      fromDebtor ||
      pick(form.deliveryAddress, 'delivery') ||
      pick(form.tkoAddress, 'tko') || { address: '', source: '' }
    );
  }

  if (requirements === '8.1') {
    return (
      fromDebtor ||
      pick(form.tkoAddress, 'tko') ||
      pick(form.deliveryAddress, 'delivery') ||
      pick(form.premisesAddress, 'premises') || { address: '', source: '' }
    );
  }

  // 3.1 / 5.1 / 6.x / 7.1 и пр. — точки поставки
  return (
    fromDebtor ||
    pick(form.deliveryAddress, 'delivery') ||
    pick(form.tkoAddress, 'tko') ||
    pick(form.premisesAddress, 'premises') || { address: '', source: '' }
  );
}

/**
 * Разбор адреса на части (ТЗ п.1-3).
 * Пример: «Московская обл., г. Королев, ул. Ленина, д. 1, кв. 3»
 */
export function parseRuAddressParts(address) {
  const text = String(address || '')
    .replace(/\u00a0/g, ' ')
    .trim();
  if (!text) {
    return { region: '', city: '', street: '', house: '', flat: '', raw: '' };
  }

  const parts = text
    .split(',')
    .map((p) => p.trim())
    .filter(Boolean);
  let region = '';
  let city = '';
  let street = '';
  let house = '';
  let flat = '';

  for (const part of parts) {
    const n = norm(part);
    if (
      !region &&
      /(обл\.|область|край|респ\.|республика|ао\b|г\.\s*москва|г\.\s*санкт|г\.\s*севастополь)/i.test(part)
    ) {
      region = part;
      continue;
    }
    if (!city && /^(г\.|город|пгт|пос\.|п\.|с\.|село|рп|район)/i.test(n)) {
      city = part;
      continue;
    }
    if (!street && /^(ул\.|улица|пр\.|проспект|пер\.|переулок|б-р|бульвар|ш\.|шоссе|наб\.|площадь|пл\.)/i.test(n)) {
      street = part;
      continue;
    }
    if (!house && /^(д\.|дом|корп\.|корпус|стр\.|строение|вл\.)/i.test(n)) {
      house = part;
      continue;
    }
    if (!flat && /^(кв\.|квартира|ком\.|комната|помещ\.|помещение)/i.test(n)) {
      flat = part;
      continue;
    }
  }

  // «г. Москва, г. Зеленоград, …» — первый токен может быть регионом-городом
  if (!region && parts[0] && /^г\./i.test(parts[0])) {
    region = parts[0];
    if (!city && parts[1] && /^г\./i.test(parts[1])) city = parts[1];
  }

  return { region, city, street, house, flat, raw: text };
}

function matchScore(row, parts) {
  let score = 0;
  const region = compactAddressPart(parts.region);
  const city = compactAddressPart(parts.city);
  const street = compactAddressPart(parts.street);
  const house = compactAddressPart(parts.house);

  if (region && compactAddressPart(row.region) === region) score += 8;
  else if (region && norm(row.region).includes(region)) score += 4;

  if (city && compactAddressPart(row.city) === city) score += 8;
  else if (city && norm(row.city).includes(city)) score += 4;

  if (street && compactAddressPart(row.street) === street) score += 10;
  else if (street && norm(row.street).includes(street)) score += 5;

  if (house && compactAddressPart(row.house) === house) score += 10;
  else if (house && norm(row.house).includes(house)) score += 4;

  return score;
}

function extractLocality(courtAddress) {
  const text = String(courtAddress || '');
  const match = text.match(/г\.\s*[^,\n]+/i);
  return match ? match[0].trim() : '';
}

/**
 * @param {string|{ region?: string, city?: string, street?: string, house?: string, flat?: string }} addressOrParts
 * @param {{ rows?: Array, kind?: 'magistrate'|'districtCourt'|'auto', statementType?: string }} [options]
 *   kind auto: statementType a/c → magistrate, b/e/d → districtCourt
 */
export function resolveSoyCourt(addressOrParts, options = {}) {
  const rows = options.rows || PODSUDNOST_SOY_ROWS;
  const parts = typeof addressOrParts === 'string' ? parseRuAddressParts(addressOrParts) : { ...addressOrParts };

  const scored = rows
    .map((row) => ({ row, score: matchScore(row, parts) }))
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score);

  const best = scored[0] || null;
  let kind = options.kind || 'auto';
  if (kind === 'auto') {
    const t = options.statementType;
    kind = t === 'b' || t === 'e' || t === 'd' ? 'districtCourt' : 'magistrate';
  }

  if (!best || best.score < 18) {
    return {
      ...emptySoyCourt(),
      kind,
      parts,
      candidates: scored.slice(0, 5).map((x) => ({ score: x.score, ...x.row })),
      score: best ? best.score : 0,
    };
  }

  const raw = kind === 'districtCourt' ? best.row.districtCourt : best.row.magistrate;
  const chunks = String(raw)
    .split(/\n| {2,}/)
    .map((s) => s.trim())
    .filter(Boolean);
  const courtName = chunks[0] || raw;
  const courtAddress = chunks.slice(1).join(', ') || '';

  return {
    ...emptySoyCourt(),
    found: true,
    kind,
    parts,
    match: best.row,
    score: best.score,
    candidates: scored.slice(0, 5).map((x) => ({ score: x.score, ...x.row })),
    courtName,
    courtAddress,
    locality: extractLocality(courtAddress || raw),
    raw,
  };
}

/** Полный цикл: адрес из формы → суд СОЮ. */
export function resolveSoyCourtForForm(form = {}) {
  const { address, source } = getJurisdictionAddress(form);
  const resolved = resolveSoyCourt(address, { statementType: form.statementType });
  return {
    ...resolved,
    source,
    sourceAddress: address,
  };
}
