/**
 * Макет: «исковое для арбитража - 9 (кредит + залог).docx»
 * Вар.4/5 + опция 9 + п.3.3 вар.1/2. Без отсебятины.
 */
import { formatDutyAmount } from '../utils/calculateStateDuty';
import { debtorDisplayName, joinDebtorNames } from '../utils/resolveDebtors';

const PLACEHOLDER_COLOR = '#C00000';
/** Образец: 10 000 (долг) + 50 000 (обращение взыскания) = 60 000 в приложениях. */
const CREDIT_DUTY = '10\u00a0000';
const FORECLOSURE_DUTY = '50\u00a0000';
const TOTAL_DUTY_WITH_FORECLOSURE = '60\u00a0000';

function label(text) {
  return { text };
}

function placeholder(text) {
  return { text, italics: true, color: PLACEHOLDER_COLOR };
}

function plain(text) {
  return { text };
}

function field(value, placeholderText) {
  const text = value != null ? String(value).trim() : '';
  return text ? plain(text) : placeholder(placeholderText || '___');
}

function blank(value) {
  const text = value != null ? String(value).trim() : '';
  return text ? plain(text) : placeholder('___');
}

function headerLine(children) {
  return { text: children, alignment: 'right' };
}

function bodyParagraph(children) {
  return { text: children, alignment: 'justify', margin: [24, 0, 0, 8] };
}

function moneyField(value, placeholderText) {
  const n = Number(value);
  return n > 0 ? label(formatDutyAmount(n)) : placeholder(placeholderText || 'сумма');
}

function optionalHeaderLine(text) {
  const value = text != null ? String(text).trim() : '';
  return value ? [headerLine([plain(value)])] : [];
}

function citizenHeaderLines(person, indexLabel) {
  const lines = [];
  const name = String(person.fio || '').trim();
  const birthday = String(person.birthday || '').trim();
  const birthplace = String(person.birthplace || '').trim();
  const inn = String(person.inn || '').trim();
  const address = String(person.address || '').trim();
  const prefix = indexLabel ? `${indexLabel}. ` : '';

  if (name) lines.push(headerLine([label(prefix), plain(name)]));
  else if (prefix) lines.push(headerLine([label(prefix.trim())]));

  if (birthday || birthplace) {
    const birthParts = [plain('родился (ась) ')];
    if (birthday) birthParts.push(plain(birthday));
    if (birthday && birthplace) birthParts.push(plain(', '));
    if (birthplace) birthParts.push(plain(birthplace));
    lines.push(headerLine(birthParts));
  }
  if (inn) lines.push(headerLine([plain(inn)]));
  if (address) lines.push(headerLine([plain(address)]));
  return lines;
}

function organizationHeaderLines(person, indexLabel) {
  const name = String(person.fio || '').trim();
  const inn = String(person.inn || '').trim();
  const ogrn = String(person.ogrn || '').trim();
  const address = String(person.address || '').trim();
  const prefix = indexLabel ? `${indexLabel}. ` : '';
  const lines = [];

  if (name) lines.push(headerLine([label(prefix), plain(name)]));
  else if (inn) lines.push(headerLine([label(prefix), plain(`ИНН ${inn}`)]));
  else if (prefix) lines.push(headerLine([label(prefix.trim())]));

  if (ogrn) lines.push(headerLine([plain(`ОГРН ${ogrn}`)]));
  if (name && inn) lines.push(headerLine([plain(`ИНН ${inn}`)]));
  if (address) lines.push(headerLine([plain(address)]));
  return lines;
}

function partyHeaderLines(person, indexLabel) {
  if (person?.type === 'organization') return organizationHeaderLines(person, indexLabel);
  return citizenHeaderLines(person, indexLabel);
}

function resolveBorrowerAndSecondaries(form = {}) {
  const borrowers = [];
  // вар.4/5 (d/e): п.8* — DataDebtorRecalc → debtorLoan (не stale debtors)
  const preferLoanDebtor = ['d', 'e'].includes(form.statementType);
  const loan = form.debtorLoan || {};
  const hasLoanDebtor =
    String(loan.fio || '').trim() || String(loan.address || '').trim() || String(loan.inn || '').trim();

  if (preferLoanDebtor && hasLoanDebtor) {
    borrowers.push({
      type: 'citizen',
      fio: String(loan.fio || '').trim(),
      birthday: loan.birthday || '',
      birthplace: loan.birthplace || '',
      inn: loan.inn || '',
      address: String(loan.address || '').trim(),
      ogrn: loan.ogrn || '',
    });
  } else {
    const fromCitizens = (form.debtors || [])
      .map((d) => ({ type: 'citizen', ...d }))
      .filter((d) => String(d.fio || '').trim() || String(d.address || '').trim());
    if (fromCitizens.length) {
      borrowers.push(...fromCitizens);
    } else if (hasLoanDebtor) {
      borrowers.push({
        type: 'citizen',
        fio: String(loan.fio || '').trim(),
        birthday: loan.birthday || '',
        birthplace: loan.birthplace || '',
        inn: loan.inn || '',
        address: String(loan.address || '').trim(),
        ogrn: loan.ogrn || '',
      });
    }
  }

  const legalInn = String(form.debtorInn || '').trim();
  if (!borrowers.length && legalInn) {
    borrowers.push({
      type: 'organization',
      fio: '',
      birthday: '',
      birthplace: '',
      inn: legalInn,
      address: '',
      ogrn: '',
    });
  }

  const guarantorClaim = form.loanInfo?.guarantorClaim;
  const includeSecondaries = guarantorClaim === 'a' || guarantorClaim === 'b';
  const secondaries = includeSecondaries
    ? (form.guarantors || [])
        .map((g) => ({
          type: g.type === 'organization' ? 'organization' : 'citizen',
          fio: String(g.fio || '').trim(),
          birthday: g.birthday || '',
          birthplace: g.birthplace || '',
          inn: g.inn || g.legalInn || '',
          address: String(g.address || '').trim(),
          ogrn: g.ogrn || '',
        }))
        .filter((g) => g.fio || g.inn || g.address)
    : [];

  return { borrowers, secondaries };
}

function splitLoanContract(raw) {
  const text = String(raw || '')
    .trim()
    .replace(/^№\s*/i, '');
  if (!text) return { number: '', date: '' };

  const withOt = text.match(/^(.*?)\s+от\s+(\d{1,2}[./]\d{1,2}[./]\d{2,4})\s*$/i);
  if (withOt) {
    return { number: withOt[1].trim().replace(/^№\s*/i, ''), date: normalizeContractDate(withOt[2]) };
  }

  const dateOnly = text.match(/^(\d{1,2}[./]\d{1,2}[./]\d{2,4})$/);
  if (dateOnly) {
    return { number: '', date: normalizeContractDate(dateOnly[1]) };
  }

  const leadingDate = text.match(/^(\d{1,2}[./]\d{1,2}[./]\d{2,4})[\s,]+(?:№\s*)?(.+)$/);
  if (leadingDate) {
    return {
      number: leadingDate[2].trim().replace(/^№\s*/i, ''),
      date: normalizeContractDate(leadingDate[1]),
    };
  }

  const trailingDate = text.match(/^(.*?)[\s,]+(\d{1,2}[./]\d{1,2}[./]\d{2,4})\s*$/);
  if (trailingDate && trailingDate[1].trim()) {
    return {
      number: trailingDate[1].trim().replace(/^№\s*/i, ''),
      date: normalizeContractDate(trailingDate[2]),
    };
  }

  return { number: text, date: '' };
}

function normalizeContractDate(raw) {
  const m = String(raw || '').match(/^(\d{1,2})[./](\d{1,2})[./](\d{2,4})$/);
  if (!m) return '';
  const dd = String(m[1]).padStart(2, '0');
  const mm = String(m[2]).padStart(2, '0');
  let yyyy = Number(m[3]);
  if (yyyy < 100) yyyy += 2000;
  return `${dd}.${mm}.${yyyy}`;
}

function appendixLine(n, childrenOrText) {
  if (typeof childrenOrText === 'string') {
    return { text: `${n}) ${childrenOrText}`, margin: [24, 0, 0, 0] };
  }
  return {
    text: [plain(`${n}) `), ...childrenOrText],
    margin: [24, 0, 0, 0],
  };
}

export function buildStatementArbitrationClaim9CreditPledgePdfDoc(form = {}) {
  const claimant = form.claimant || {};
  const bank = form.bankDetails || {};
  const loanInfo = form.loanInfo || {};
  const penaltyLoan = form.penaltyLoan || {};
  const penaltyDetails = form.penaltyDetails || {};
  const surety = (form.suretyContracts || [])[0] || {};
  const suretyContract = splitLoanContract(surety.contract);
  const pledges = (form.pledgeContracts || []).filter(
    (p) => String(p.contract || '').trim() || String(p.subject || '').trim() || Number(p.pledgeValue) > 0
  );
  const signerFio = form.signer && form.signer.fio;

  const claimantName = String(claimant.name || bank.recipientName || '').trim();
  const claimantInn = String(claimant.inn || bank.inn || '').trim();
  const claimantAddress = String(claimant.address || '').trim();
  const contract = splitLoanContract(loanInfo.loanContract);
  const isEarly = loanInfo.collectType === 'a';
  const toGuarantors = loanInfo.guarantorClaim === 'a';
  const toPledgors = loanInfo.guarantorClaim === 'b';
  const loanClaimType = String(loanInfo.loanClaimType || '');
  /** п.3.3 вар.1 + п.3.3.1 «к залогодателям»: долг + обращение взыскания. Вар.2 — только долг. */
  const askForeclosure = loanClaimType === 'a' && toPledgors;
  const appsDuty = askForeclosure ? TOTAL_DUTY_WITH_FORECLOSURE : CREDIT_DUTY;

  const { borrowers, secondaries } = resolveBorrowerAndSecondaries(form);
  const allParties = [...borrowers, ...secondaries];
  const partyFios = joinDebtorNames(allParties);
  const borrowerName = debtorDisplayName(borrowers[0] || {});

  const loanCalc = loanInfo.loanCalc || {};
  const schedule = loanInfo.paymentScheduleData || {};
  const creditAmount = loanCalc.creditAmount || schedule.creditAmount || '';
  const loanTerm = loanCalc.termLabel || schedule.termLabel || '';
  const loanRate =
    loanCalc.annualRatePercent != null
      ? String(loanCalc.annualRatePercent)
      : schedule.annualRatePercent != null
        ? String(schedule.annualRatePercent)
        : '';

  const overdueTotal = loanCalc.overdueTotal || '';
  const overdueInterest = loanCalc.overdueInterest || '';
  const remainingCredit = loanCalc.remainingCredit || '';
  const loanPenalty = loanCalc.penalty || {};
  const penaltyAmount = loanPenalty.penaltyTotal || '';
  const penaltyFrom = loanPenalty.penaltyFrom || '';
  const penaltyTo = loanPenalty.penaltyTo || '';

  const borrowerBlocks = borrowers.flatMap((d, index) => {
    const lines = partyHeaderLines(d, String(index + 1));
    const needGap = index < borrowers.length - 1 || secondaries.length > 0;
    return needGap ? [...lines, headerLine([plain(' ')])] : lines;
  });

  const secondaryBlocks = secondaries.flatMap((g, index) => {
    const n = borrowers.length + index + 1;
    const lines = partyHeaderLines(g, String(n));
    return index < secondaries.length - 1 ? [...lines, headerLine([plain(' ')])] : lines;
  });

  const content = [
    headerLine([label('Арбитражный суд')]),
    headerLine([plain(' ')]),
    headerLine([label('Истец:')]),
    ...optionalHeaderLine(claimantName),
    ...(claimantInn ? [headerLine([plain(`ИНН ${claimantInn}`)])] : []),
    ...optionalHeaderLine(claimantAddress),
    headerLine([plain(' ')]),
    headerLine([label('Ответчики:')]),
    ...borrowerBlocks,
    ...secondaryBlocks,

    {
      text: 'Исковое заявление',
      alignment: 'center',
      bold: true,
      margin: [0, 24, 0, 24],
    },

    bodyParagraph([
      plain('Во исполнение кредитного договора № '),
      blank(contract.number),
      plain(' от '),
      blank(contract.date),
      plain(' '),
      field(borrowerName, 'такому-то'),
      plain(' предоставлен кредит на сумму '),
      moneyField(creditAmount, 'сумма'),
      plain(' руб. сроком на '),
      blank(loanTerm),
      plain(' при условии выплаты '),
      blank(loanRate || penaltyDetails.bankRate || penaltyDetails.debtRate),
      plain(' % годовых.'),
    ]),
    bodyParagraph([
      plain(
        'Согласно п. 1 ст. 810 ГК РФ заемщик обязан возвратить займодавцу полученную сумму займа в срок и в порядке, которые предусмотрены договором займа.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Выпиской по ссудному счету подтверждается несвоевременное внесение заемщиком ряда платежей согласно графику и пропуск остальных.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Сумма просроченной задолженности (в части суммы кредита и процентов за пользование) составляет '
      ),
      moneyField(overdueTotal, 'сумма'),
      plain(' руб., из которой '),
      moneyField(overdueInterest, 'сумма'),
      plain(' руб. – это просроченные проценты.'),
    ]),
    bodyParagraph([
      plain(
        'Как следует из п. 2 ст. 811 ГК РФ при нарушении заемщиком срока возврата очередной части займа у займодавца возникает право требовать от заемщика досрочного возврата всей оставшейся суммы займа вместе с процентами за пользование займом, причитающимися на момент его возврата.'
      ),
    ]),
  ];

  if (isEarly) {
    content.push(
      bodyParagraph([
        plain('Сумма невозвращенного кредита в данном случае составляет '),
        moneyField(remainingCredit, 'сумму'),
        plain(' руб.'),
      ])
    );
  }

  content.push(
    bodyParagraph([
      plain('При этом, поскольку заемщиком допущена просрочка кредитным договором (пункт '),
      blank(penaltyLoan.clauseNumber),
      plain(') на этот случай предусмотрена неустойка в размере '),
      blank(penaltyDetails.debtRate || penaltyDetails.bankRate),
      plain(' от суммы просроченной задолженности за каждый день просрочки.'),
    ]),
    bodyParagraph([
      plain(
        'Такая неустойка начисляется до момента полного возврата всей суммы кредита (абз. 2 п. 3 ст. 425 ГК РФ).'
      ),
    ]),
    bodyParagraph([
      plain('По расчету истца (прилагается) сумма такой неустойки составляет '),
      moneyField(penaltyAmount, 'размер'),
      plain(' руб.'),
    ])
  );

  if (toGuarantors) {
    content.push(
      bodyParagraph([
        plain('В обеспечение возврата суммы кредита предоставлено поручительство на сумму '),
        moneyField(surety.amount, 'сумма'),
        plain(' руб. (договор № '),
        blank(suretyContract.number),
        plain(' от '),
        blank(suretyContract.date),
        plain(').'),
      ]),
      bodyParagraph([
        plain(
          'В соответствии с п. 1 ст. 363 ГК РФ при неисполнении или ненадлежащем исполнении должником обеспеченного поручительством обязательства поручитель и должник отвечают перед кредитором солидарно.'
        ),
      ]),
      bodyParagraph([
        plain('Абзацем 2 пункта 5 постановления Пленума Верховного Суда РФ от 21.01.2016 № 1 также разъяснено, что,'),
      ]),
      bodyParagraph([
        plain(
          'если лица, не в пользу которых принят судебный акт, являются солидарными должниками, то судебные издержки также возмещаются указанными лицами в солидарном порядке.'
        ),
      ]),
      bodyParagraph([
        plain(
          'Исходя из этого госпошлина за предъявление одним кредитором к нескольким солидарным должникам требований о взыскании общей задолженности и пени уплачивается как за одно требование, т.к. обязательство для таких должников перед кредитором является единым (п. 1 ст. 323 ГК РФ).'
        ),
      ])
    );
  }

  if (toPledgors) {
    content.push(
      bodyParagraph([plain('Также требования о возврате кредита обеспечены залогом следующего имущества:')])
    );
    for (const p of pledges.length ? pledges : [{ subject: '', pledgeValue: '', contract: '' }]) {
      const pledgeContract = splitLoanContract(p.contract);
      content.push(
        bodyParagraph([
          plain('- '),
          field(p.subject, 'существо, название, рег. номер предмета залога, находящееся по адресу: адрес'),
        ]),
        bodyParagraph([
          plain('с залоговой стоимостью – '),
          moneyField(p.pledgeValue, 'сумма'),
          plain(' руб.'),
        ]),
        bodyParagraph([
          plain('Залоги выданы по договору № '),
          blank(pledgeContract.number),
          plain(' от '),
          blank(pledgeContract.date),
          plain(' (обеспечивая требования в пределах '),
          moneyField(p.pledgeValue, 'сумма'),
          plain(' руб. или без ограничения суммой, не включая неустойку)'),
        ])
      );
    }
    if (askForeclosure) {
      content.push(
        bodyParagraph([
          plain(
            'Согласно п. 1 ст. 334 ГК РФ в силу залога при неисполнении / ненадлежащем исполнении обеспеченного им обязательства должником залогодержатель вправе преимущественно перед другими лицами получить удовлетворение из стоимости предмета залога.'
          ),
        ]),
        bodyParagraph([
          plain(
            'Данная норма, как и другие положения о залоге (ст. 348, 349 ГК РФ) не предусматривают залог в виде субсидиарной меры защиты прав кредитора, а потому допускают одновременно как получение исполнения с заемщика, так и за счет предмета залога до полного удовлетворения требований залогодержателя,'
          ),
        ]),
        bodyParagraph([
          plain(
            'а также не требуют от залогодержателя обращения взыскания на залог лишь в случае недостаточности имущества у заемщика.'
          ),
        ]),
        bodyParagraph([
          plain(
            'В связи с чем залогодержатель вправе в случае просрочки заемщика одновременно взыскать как с него просроченный им долг, так и обратить взыскание на залог, обеспечивающий выплату этого долга.'
          ),
        ]),
        bodyParagraph([
          plain('Как следует из п. 2 ст. 348 ГК РФ, обращение взыскания на заложенное имущество допускается, если одновременно:'),
        ]),
        bodyParagraph([plain('1) сумма неисполненного обязательства превышает 5 % от стоимости заложенного имущества,')]),
        bodyParagraph([plain('2) период просрочки исполнения обязательства, обеспеченного залогом, превышает 3 месяца.')]),
        bodyParagraph([plain('В данном случае такие условия соблюдены.')]),
        bodyParagraph([
          plain(
            'В соответствии с п. 3 ст. 340 ГК РФ согласованная сторонами залоговая стоимость признается ценой реализации (начальной продажной ценой) предмета залога при обращении на него взыскания.'
          ),
        ])
      );
    }
  }

  content.push(
    bodyParagraph([plain('На основании изложенного, а также ст. 125, 126 АПК РФ,')]),
    { text: 'ПРОШУ:', alignment: 'center', bold: true, margin: [0, 12, 0, 12] },
    bodyParagraph([
      plain('- взыскать в солидарном порядке с '),
      field(partyFios, 'таких-то'),
      plain(' задолженность по возврату кредита в размере '),
      moneyField(remainingCredit || overdueTotal, 'сумма'),
      plain(' руб., проценты за пользование в размере '),
      moneyField(overdueInterest, 'сумма'),
      plain(' руб., неустойку за период с '),
      blank(penaltyFrom),
      plain(' по '),
      blank(penaltyTo),
      plain(' в размере '),
      moneyField(penaltyAmount, 'сумма'),
      plain(' руб., расходы по уплате госпошлины '),
      label(CREDIT_DUTY),
      plain(' руб.'),
    ])
  );

  if (askForeclosure) {
    const list = pledges.length ? pledges : [{ subject: '', pledgeValue: '' }];
    for (const p of list) {
      content.push(
        bodyParagraph([plain('- обратить взыскание на заложенное имущество:')]),
        bodyParagraph([
          field(p.subject, 'существо, название, рег. номер предмета залога, находящееся по адресу: адрес'),
        ]),
        bodyParagraph([
          plain('Установить начальную продажную стоимость для реализации его с торгов в размере '),
          moneyField(p.pledgeValue, 'сумма'),
          plain(' руб.'),
        ])
      );
    }
    content.push(
      bodyParagraph([
        plain('Взыскать с '),
        field(partyFios, 'таких-то'),
        plain(' расходы по уплате госпошлины в размере '),
        label(FORECLOSURE_DUTY),
        plain(' руб. за обращение с этим требованием.'),
      ])
    );
  }

  content.push({ text: 'Приложения:', margin: [24, 12, 0, 4] });

  let n = 1;
  content.push(appendixLine(n++, 'почтовые квитанции о направлении заявления в адрес ответчиков,'));
  content.push(
    appendixLine(n++, [
      plain('доказательства уплаты госпошлины в размере '),
      label(appsDuty),
      plain(' руб.,'),
    ])
  );
  content.push(
    appendixLine(n++, [
      plain('кредитный договор № '),
      blank(contract.number),
      plain(' от '),
      blank(contract.date),
    ])
  );
  content.push(appendixLine(n++, 'мемориальные ордера на выдачу кредита,'));
  content.push(appendixLine(n++, 'выписка по ссудному счету,'));
  if (isEarly) {
    content.push(appendixLine(n++, 'требование о досрочном возврате кредита,'));
  }
  content.push(appendixLine(n++, 'расчет неустойки,'));
  if (toGuarantors) {
    content.push(
      appendixLine(n++, [
        plain('договор поручительства № '),
        blank(suretyContract.number),
        plain(' от '),
        blank(suretyContract.date),
      ])
    );
  }
  if (toPledgors) {
    const list = pledges.length ? pledges : [{ contract: '' }];
    for (const p of list) {
      const pc = splitLoanContract(p.contract);
      content.push(
        appendixLine(n++, [
          plain('договор залога № '),
          blank(pc.number),
          plain(' от '),
          blank(pc.date),
        ])
      );
    }
  }
  content.push(appendixLine(n++, 'выписки из ЕГРЮЛ и/или ЕГРИП на сторон,'));
  content.push(appendixLine(n++, 'копия доверенности представителя.'));

  content.push({ text: [field(signerFio, 'ФИО подписанта')], margin: [24, 24, 0, 0] });

  return {
    content,
    defaultStyle: { fontSize: 11 },
    pageMargins: [56, 56, 56, 56],
  };
}
